<script setup lang="ts">
import FieldSelector from '../components/FieldSelector.vue'
import {ref,computed,onMounted,watch} from 'vue'
import {useRoute} from 'vue-router'
import {cropApi} from '../api/crop'
import {useFarm} from '../stores/farm'
import type {Page,Harvest,HarvestSummary} from '../../shared/contracts'
const farm=useFarm(),route=useRoute(),tab=ref('harvest'),busy=ref(false),message=ref(''),error=ref(''),records=ref<Page<Harvest>>(),page=ref(1)
const summary=ref<HarvestSummary>(),summaryError=ref('')
const selectedRidge=computed(()=>farm.ridges.find(r=>r.id===(tab.value==='harvest'?form.value.ridgeId:plant.value.ridgeId)))
const selectedTotal=computed(()=>summary.value?.byRidge.find(r=>r.ridgeId===selectedRidge.value?.id))
async function loadSummary(){summaryError.value='';try{summary.value=await cropApi.harvestSummary()}catch(e){summaryError.value=(e as Error).message}}
watch(()=>farm.dashboard?.updatedAt,loadSummary)
const today=new Date().toISOString().slice(0,10)
const form=ref({ridgeId:typeof route.query.ridge==='string'?route.query.ridge:'',date:today,quantity:1,finish:false,note:''})
const plant=ref({ridgeId:'',cropId:'tomato',plants:40,plantedAt:today,batch:''})
const selectedId=computed({get:()=>tab.value==='harvest'?form.value.ridgeId:plant.value.ridgeId,set:(id:string)=>{if(tab.value==='harvest')form.value.ridgeId=id;else plant.value.ridgeId=id}})
const active=computed(()=>farm.ridges.filter(r=>r.active)),empty=computed(()=>farm.ridges.filter(r=>!r.active))
onMounted(async()=>{if(form.value.ridgeId&&!active.value.some(r=>r.id===form.value.ridgeId)){if(empty.value.some(r=>r.id===form.value.ridgeId)){plant.value.ridgeId=form.value.ridgeId;tab.value='plant'}form.value.ridgeId=''}await load();await loadSummary()})
async function load(){try{records.value=await cropApi.harvests(page.value)}catch(e){error.value=(e as Error).message}}
async function submit(){error.value='';message.value='';busy.value=true;try{if(tab.value==='harvest'){await cropApi.harvest(form.value);message.value='采收记录已保存';form.value.finish=false;form.value.note=''}else{await cropApi.plant(plant.value);message.value='种植批次已创建';plant.value.ridgeId='';plant.value.batch=''}await farm.refresh();await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function flip(n:number){page.value=n;await load()}
</script><template><div class="filters"><FieldSelector :disabled="busy"/></div><div class="two-col management"><section class="panel"><div class="tabs"><button :class="{active:tab==='harvest'}" @click="tab='harvest'">登记采收</button><button :class="{active:tab==='plant'}" @click="tab='plant'">新增种植</button></div><p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><form @submit.prevent="submit"><template v-if="tab==='harvest'"><label>采收田垄<select v-model="form.ridgeId" required><option value="" disabled>选择在种田垄</option><option v-for="r in active" :key="r.id" :value="r.id">{{r.number}}号垄 · {{farm.cropName(r.cropId)}}</option></select></label><div class="two-col"><label>采收日期<input type="date" v-model="form.date" :max="today" required/></label><label>采收重量（kg）<input type="number" min="0.01" step="0.01" v-model.number="form.quantity" required/></label></div><label>备注<textarea v-model="form.note" maxlength="500" placeholder="记录本次采收情况（选填）"/></label><label class="checkbox"><input type="checkbox" v-model="form.finish"/>确认本批次种植已结束</label><p class="muted">勾选后田垄变为空垄，在种苗数清零，已有采收记录保留。</p></template><template v-else><label>空垄<select v-model="plant.ridgeId" required><option value="" disabled>选择待种植田垄</option><option v-for="r in empty" :key="r.id" :value="r.id">{{r.number}}号垄</option></select></label><label>作物品种<select v-model="plant.cropId"><option v-for="c in farm.crops" :value="c.id" :key="c.id">{{c.name}} · {{c.cultivar}}</option></select></label><label>批次名称<input v-model="plant.batch" maxlength="60" placeholder="例如：冬季第一批" required/></label><div class="two-col"><label>种植日期<input type="date" v-model="plant.plantedAt" :max="today" required/></label><label>初始苗数<input type="number" v-model.number="plant.plants" min="1" max="10000" step="1" required/></label></div></template><button class="primary" :disabled="busy">{{busy?'保存中…':'保存记录'}}</button></form></section><section class="panel harvest-overview"><h2>采收概况</h2><p v-if="summaryError" class="error-banner">{{summaryError}} <button @click="loadSummary">重试</button></p><template v-else-if="summary"><p class="muted">本周：{{summary.weekStart}} 至 {{summary.today}}</p><div class="table-wrap"><table><thead><tr><th>作物</th><th>今日 kg</th><th>本周 kg</th><th>累计 kg</th></tr></thead><tbody><tr v-for="c in summary.byCrop" :key="c.cropId"><td>{{farm.crops.find(x=>x.id===c.cropId)?.name}}</td><td>{{c.todayKg}}</td><td>{{c.weekKg}}</td><td>{{c.totalKg}}</td></tr></tbody></table></div></template><p v-else class="muted">正在加载采收统计…</p><div class="selected-ridge"><h2>田垄详情</h2><label class="ridge-detail-selector">选择田垄查看详情<select v-model="selectedId"><option value="">{{tab==='harvest'?'请选择在种田垄':'请选择空垄'}}</option><option v-for="r in (tab==='harvest'?active:empty)" :key="r.id" :value="r.id">{{r.number}}号垄{{r.active?' · '+farm.cropName(r.cropId):' · 空垄'}}</option></select></label><p class="muted selection-sync">与左侧{{tab==='harvest'?'采收登记':'新增种植'}}表同步选择</p><template v-if="selectedRidge"><dl><div><dt>田垄</dt><dd>{{selectedRidge.number}}号垄</dd></div><template v-if="selectedRidge.active"><div><dt>作物</dt><dd>{{farm.cropName(selectedRidge.cropId)}}</dd></div><div><dt>种植批次</dt><dd>{{selectedRidge.batch}}</dd></div><div><dt>种植日期</dt><dd>{{selectedRidge.plantedAt}}</dd></div><div><dt>本批累计采收</dt><dd>{{selectedTotal?.quantity??'—'}} kg / {{selectedTotal?.count??'—'}} 次</dd></div><div><dt>巡检状态</dt><dd>{{farm.status(selectedRidge)}}</dd></div><div><dt>综合成熟评分</dt><dd>{{farm.harvestAssessment(selectedRidge)?.score==null?'待有效检测':farm.harvestAssessment(selectedRidge)!.score+' 分'}}</dd></div><div><dt>采收提醒</dt><dd>{{farm.harvestAssessment(selectedRidge)?.label??'待检测'}}</dd></div></template><div v-else><dt>状态</dt><dd>空垄 · 可新建种植批次</dd></div></dl><RouterLink :to="'/ridges?id='+selectedRidge.id" class="text-link">查看田垄与检测图片 →</RouterLink></template><p v-else class="muted">请使用上方下拉框选择田垄，即可查看详情。</p></div></section></div><section class="panel"><div class="panel-title"><h2>采收记录</h2><span class="muted">共 {{records?.total||0}} 条</span></div><div class="table-wrap"><table><thead><tr><th>日期</th><th>田垄</th><th>批次</th><th>重量</th><th>状态</th></tr></thead><tbody><tr v-for="h in records?.items" :key="h.id"><td>{{h.date}}</td><td>{{farm.ridges.find(r=>r.id===h.ridgeId)?.number}}号垄</td><td>{{h.batch}}</td><td>{{h.quantity}} {{h.unit}}</td><td><span class="badge">{{h.finish?'种植结束':'部分采收'}}</span></td></tr></tbody></table></div><div class="pagination"><button class="secondary" :disabled="page===1" @click="flip(page-1)">上一页</button><span>第 {{page}} 页</span><button class="secondary" :disabled="!records||page*10>=records.total" @click="flip(page+1)">下一页</button></div></section></template>